# VENDORED COPY -- generated by tools/build_addon.py from core/motionpool.py
# Edit core/motionpool.py, not this file.
#!/usr/bin/env python3
r"""motionpool.py -- WHICH motion clips a skeleton solve should be measured on.

`bonejoint` can tell an articulation from a coincidence given frames. It cannot
tell you which frames to hand it, and that turns out to decide the answer.

THE DEFECT THIS EXISTS TO FIX, MEASURED
---------------------------------------
The Blender importer used to `os.walk` the LOOSE `c3/000N` directory and take
the first ten `.c3` files in sorted-name order. Two things follow, and both
were live:

1. **THE POOL WAS WHATEVER THE INSTALL HAPPENED TO LEAVE UNPACKED.** On the
   CCO install, body 0003 declares 433 clips and ships 287 of them: **266
   exist only inside `c3.wdf` and 21 are loose**. The loose ones are weapon
   sets 500/611/756, and the **unarmed set `000` -- 124 distinct clips behind
   9,743 index keys -- has not one loose file**. On 5517 the split is the
   other way, ~178 loose of ~454 declared. So two installs of the same game
   solved the same body from disjoint evidence, and neither was asked what it
   actually ships.

2. **THE FIRST FILE SET THE RIG.** `want` was pinned to the first accepted
   file's `bone_count` and everything else was compared to it, so a 26-bone
   clip sorting first would have reduced the solve to that one file.
   `c3/0002/000/451.c3` is 26 bones and `c3/0002/611/452.c3` is 60, against a
   modal 84 -- both archive-only today, which is the only reason it never
   fired. The rig is a property of the SHAPE, so the modal count decides and
   the outliers are dropped WITH A REASON.

AND THE PART THAT IS NOT ABOUT REACHING MORE FILES
--------------------------------------------------
More frames is not better. **A clip in which a pair never bends is not
evidence about that pair** -- it solves to zero for every point, so it is
silence, not agreement. Body 0003's ten unarmed actions hold the hand-to-finger
pairs rigid; its own idle holds ALL 300 pairs of its 25 skinned bones below the
motion floor. So the pool has to be chosen for ARTICULATION COVERAGE -- clips
that between them bend everything -- and `bonejoint.solve_from_clips` then
takes one verdict per clip rather than pooling frames that disagree.

Measured, CCO body 003188495: the coverage-ranked pool of 16 clips reproduces
the anatomy in `docs/bone_labels_2026-09-21.md` section 1 edge for edge, and
the head/neck chain inverts (`006 -> 004`, `005 -> 006`) if the clips are taken
in name order instead of by coverage. The ranking is doing real work.

WHAT IS IN COre AND WHAT IS NOT
-------------------------------
Reading a `MOTI` chunk needs `effects.parse_moti`, which lives in `tools/`, and
COre never reaches up there (`core/README.md`, gated by
`tools/test_viewer.py::CoreBoundary`). So `gather_clips` takes a `load`
CALLABLE. That is not a workaround for the boundary -- it is what makes the
selection testable with synthetic clips and no client at all, which is how
`tests/test_motionpool.py` runs.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Iterable, Optional

from . import bonejoint
from . import dbcshadow

#: Where one row of the merged table came from. Identical strings to
#: `tools/anim.py`'s, which imports them from here -- ONE home for the rule,
#: because a second copy of the ini/dbc merge is how the two drift apart and
#: `dbcshadow`'s own docstring says so.
SRC_INI = "ini/3dmotion.ini"
SRC_INI_PATH = "ini/3dmotion.ini (key re-spelled from the row's path)"
SRC_DBC = "compiled twin (.dbc) -- the live table; the .ini is the decoy"

#: `c3/<shape>/<weaponset>/<action>.c3`, the one row layout whose key can be
#: rebuilt from the path. Rows that are not this shape -- chained `-N` stems,
#: the flat NPC family -- are left alone.
_ROW = re.compile(r"^c3/(\d{4})/(\d{3})/(\d{1,3})\.c3$", re.I)

#: Fewest keys worth loading from one clip. One key is worthless on its own
#: (`bonejoint`'s docstring: a single frame solves every pair perfectly), and a
#: handful is where a residual starts to mean something.
MIN_KEYS = 4

#: Stop adding clips once the pool is this big AND coverage has stopped
#: growing. 500 frames over ~16 clips solves in ~2 s on 300 pairs; the tree was
#: MEASURED IDENTICAL from 28 frames to 2,819 on CCO body 0003, so this buys
#: residual tightness rather than a different answer -- one spurious pair drops
#: between one clip and two.
FRAME_TARGET = 500

#: Never exceed this, whatever coverage is still missing. The solve is
#: O(pairs x frames) in pure Python: 4,129 frames on 25 bones is ~11 s, and the
#: whole declared pool for one shape is ~10,300 frames, which is ~27 s for an
#: answer that stopped changing two orders of magnitude earlier.
FRAME_BUDGET = 4000


@dataclass
class MotionRows:
    """`ini/3dmotion.ini` merged with its compiled twin -- rows, not lookups.

    `raw` is ``{key: logical path}``. This is the part of `tools/anim.py`'s
    `MotionIndex` that has no opinion about lookup order, extracted so the
    Blender add-on can share it: `anim.py` is a 1,700-line CLI module and
    vendoring it into the add-on to reach one dict would have been the wrong
    trade, but re-implementing the merge next to it would have been worse.
    """
    raw: dict = field(default_factory=dict)
    source: dict = field(default_factory=dict)
    ini_file: Optional[Path] = None
    dbc_file: Optional[Path] = None
    row_count: int = 0
    duplicate_rows: int = 0
    conflicting_rows: int = 0


def motion_rows(root: Path | str) -> MotionRows:
    """Read and merge the motion table for one install.

    The ini first, then the compiled `.dbc` twin OVER it where one exists,
    because from 5517 on the ini is a 2009 decoy and reading only it is what
    left every 6090 body in a T-pose. Path-derived key spellings are added but
    never allowed to replace a row the file states outright.
    """
    out = MotionRows()
    p = Path(root) / "ini" / "3dmotion.ini"
    out.ini_file = p
    if p.is_file():
        rebuilt: list = []
        for line in p.read_text("latin-1", errors="replace").splitlines():
            if "=" not in line:
                continue
            k, v = line.split("=", 1)
            k = k.strip()
            if not k:
                continue
            v = v.strip().replace(chr(92), "/")
            out.row_count += 1
            if k in out.raw:
                out.duplicate_rows += 1
                out.conflicting_rows += (out.raw[k] != v)
            out.raw[k] = v
            out.source[k] = SRC_INI
            m = _ROW.match(v)
            if m:
                rebuilt.append((str(int(m.group(1))) + m.group(2)
                                + m.group(3).zfill(3), v))
        # The official plaintext ini pads the body-motion key to TEN wide
        # where CCO writes it seven; on the bases with no dbc to rebuild it,
        # every body-motion lookup missed silently. Additive only, and not
        # counted in `row_count`, which reports what the file itself carries.
        for k, v in rebuilt:
            if k not in out.raw:
                out.raw[k] = v
                out.source[k] = SRC_INI_PATH
    # Asked through `dbcshadow`, the one place that answers "is this ini
    # shadowed on this base", rather than spelling the twin's name here.
    pdbc = dbcshadow.compiled_twin(p)
    out.dbc_file = pdbc
    if pdbc is not None:
        from . import dbc as dbcmod
        for mv in dbcmod.Rsdb.parse(pdbc.read_bytes()).paths.values():
            mv = mv.replace(chr(92), "/")
            m = _ROW.match(mv)
            if not m:
                continue
            k = str(int(m.group(1))) + m.group(2) + m.group(3).zfill(3)
            out.row_count += 1
            if k in out.raw:
                out.duplicate_rows += 1
                out.conflicting_rows += (out.raw[k] != mv)
            out.raw[k] = mv
            out.source[k] = SRC_DBC
    return out


def clips_for_shape(rows: MotionRows, shape: str) -> list:
    """Every DISTINCT clip path the table declares for one body shape.

    Deduplicated and sorted, because the table names the same file from many
    keys -- CCO's 9,743 unarmed KEYS for body 0003 resolve to far fewer files.

    Matched on the `c3/<shape>/` prefix rather than by re-splitting the key, so
    rows whose weapon-set field is not a 3-digit code are still found: CCO's
    table really does carry `c3/0003/Shield-With/Sword/403.c3`, it really is in
    `c3.wdf`, and it really is an 84-bone clip of this rig.
    """
    pre = ("c3/%s/" % shape).lower()
    return sorted({v for v in rows.raw.values()
                   if isinstance(v, str) and v.lower().startswith(pre)})


@dataclass
class Clip:
    """One motion file that is a candidate for the solve.

    `frames` may be EMPTY on a clip that has been probed and released -- see
    `gather_clips(keep_frames=False)`. `key_count` is therefore a field and not
    `len(frames)`: the count outlives the frames, and the frame budget is spent
    against candidates whose frames are no longer held.
    """
    logical: str
    source: str            # `Located.source`: "loose", "c3.wdf", ...
    bone_count: int
    frames: list           # what `bonejoint.matrices_by_key` returns
    key_count: int = 0
    #: Which pairs this clip articulates. `None` means NOT YET PROBED, which
    #: is different from "probed and articulates nothing" -- an idle really
    #: does move no pairs at all (body 0003's, all 300 of them).
    moving: Optional[set] = None

    def __post_init__(self):
        if not self.key_count:
            self.key_count = len(self.frames)


def gather_clips(logicals: Iterable[str], locate: Callable, read: Callable,
                 load: Callable, *, min_keys: int = MIN_KEYS,
                 pairs=None, probe: int = bonejoint.PROBE_FRAMES,
                 min_motion: float = bonejoint.MIN_RELATIVE_MOTION,
                 keep_frames: bool = True) -> tuple:
    """-> ``(clips, missing)``. Read and parse every clip that IS present.

    `locate(logical) -> Located|None`, `read(logical) -> bytes` and
    `load(bytes) -> (bone_count, frames)|None` are passed in: the first two are
    `AssetRoot`'s, and `load` is the caller's MOTI parse (see the module
    docstring for why that is not imported here).

    `missing` is the declared-but-absent list. It is returned rather than
    dropped because "this install declares 433 clips and ships 287" is a fact
    about the install worth reporting, and 7878 declaring art it never shipped
    is why that habit exists in this tree at all.

    PROBE-AND-RELEASE, WHICH IS NOT AN OPTIMISATION BUT A LIMIT
    ----------------------------------------------------------
    Pass `pairs` and `keep_frames=False` to probe each clip's articulation
    coverage AS IT IS READ and drop its frames immediately. MEASURED on CCO:
    one 501-key 84-bone clip holds **25.7 MB** of Python tuples -- 51 KB per
    frame -- so a shape's ~10,300 candidate frames are **~526 MB**, and all
    four shapes **~2.1 GB**. The pool those candidates exist to choose is ~500
    frames, **~26 MB**. Holding the other 95% to pick from it is what makes an
    add-on unusable on a normal machine, so the caller keeps `moving` and
    `key_count` -- a few KB per clip -- and re-reads the handful it selects.
    """
    clips, missing = [], []
    for logical in logicals:
        loc = locate(logical)
        if loc is None:
            missing.append(logical)
            continue
        try:
            got = load(read(logical))
        except Exception:                                    # noqa: BLE001
            got = None
        if got is None:
            continue
        bone_count, frames = got
        if len(frames) < min_keys:
            continue
        clip = Clip(logical, getattr(loc, "source", "?"), int(bone_count),
                    frames, key_count=len(frames))
        if pairs is not None:
            clip.moving = bonejoint.probe_moving(frames, pairs, probe=probe,
                                                 min_motion=min_motion)
        if not keep_frames:
            clip.frames = []
        clips.append(clip)
    return clips, missing


def on_rig(clips: list) -> tuple:
    """-> ``(kept, dropped, modal)``. Split the clips by the SHAPE's rig.

    The modal count, not the first file's. `dropped` is
    ``[(logical, bone_count), ...]`` so the caller can say WHICH clips were
    excluded and why instead of silently solving on fewer files -- the failure
    this replaces was invisible precisely because it looked like a smaller
    sample rather than an error.
    """
    if not clips:
        return [], [], None
    hist: dict = {}
    for c in clips:
        hist[c.bone_count] = hist.get(c.bone_count, 0) + 1
    # Ties by the LOWER bone count would pick a stub rig, by the higher a
    # one-off. Neither happens on the shipped corpus (the modal count is 81 for
    # shape 0001 and 84 for 0002-0004, with 261-294 of ~290 clips agreeing), so
    # the tiebreak is STATED rather than measured: most clips, then most bones.
    modal = max(hist.items(), key=lambda kv: (kv[1], kv[0]))[0]
    kept = [c for c in clips if c.bone_count == modal]
    dropped = [(c.logical, c.bone_count) for c in clips
               if c.bone_count != modal]
    return kept, dropped, modal


@dataclass
class Pool:
    """The clips chosen for one solve, and what the choice left behind."""
    clips: list = field(default_factory=list)
    modal_bone_count: Optional[int] = None
    off_rig: list = field(default_factory=list)
    missing: list = field(default_factory=list)
    considered: int = 0
    uncovered: list = field(default_factory=list)

    @property
    def frame_count(self) -> int:
        return sum(c.key_count for c in self.clips)

    def digest(self) -> str:
        """A short stable id for THIS pool, so a report names its evidence.

        Over the clips' logical paths and key counts in pool order -- not over
        their bytes, which would mean re-reading 70 MB to print twelve
        characters. Two installs that select the same paths with the same key
        counts have solved the same problem; a pool that gained a clip or
        picked a different one gets a different digest.
        """
        import hashlib
        h = hashlib.sha256()
        for c in self.clips:
            h.update(("%s:%d\n" % (c.logical, c.key_count)).encode("utf-8"))
        return h.hexdigest()[:12]


def select_pool(clips: list, bones, *, frame_target: int = FRAME_TARGET,
                frame_budget: int = FRAME_BUDGET,
                probe: int = bonejoint.PROBE_FRAMES,
                min_motion: float = bonejoint.MIN_RELATIVE_MOTION) -> Pool:
    """Choose clips for ARTICULATION COVERAGE, then for frames.

    Greedy on new pairs covered, because coverage is the property that decides
    whether a joint can be seen at all: a pair no clip in the pool bends is
    unanswerable however many frames are stacked. Ties break toward the clip
    that bends MORE pairs overall, then the SHORTER clip, then the name -- so
    the result does not depend on dict order and two runs on one install agree.

    Coverage saturates fast (one lively CCO clip bends all 300 pairs of body
    0003), and stopping there would leave 28 frames, where a second clip drops
    a spurious pair. So selection continues to `frame_target` and only then
    requires new coverage to keep going.

    `uncovered` is the honest remainder: pairs NO candidate clip articulates.
    Those reach `bonejoint.unresolved_pairs` as abstentions and must stay
    unresolved rather than being attached to whatever solved cleanly by
    accident, which is the 10-12/10-14/18-22 failure in one sentence.
    """
    bs = sorted({int(b) for b in bones})
    pairs = [(a, b) for i, a in enumerate(bs) for b in bs[i + 1:]]
    pool = Pool(considered=len(clips))
    if not clips or not pairs:
        pool.clips = list(clips)
        pool.uncovered = list(pairs)
        return pool
    for c in clips:
        # `None` means not yet probed; an EMPTY set is a real answer and must
        # not be recomputed, both because it costs and because a clip probed
        # by `gather_clips` has already released its frames and would come
        # back articulating nothing at all.
        if c.moving is None:
            c.moving = bonejoint.probe_moving(c.frames, pairs, probe=probe,
                                              min_motion=min_motion)
    covered: set = set()
    rest = list(clips)
    chosen: list = []
    frames = 0
    while rest:
        rest.sort(key=lambda c: (-len(c.moving - covered), -len(c.moving),
                                 c.key_count, c.logical))
        c = rest[0]
        gain = c.moving - covered
        if frames >= frame_target and not gain:
            break
        if chosen and frames + c.key_count > frame_budget:
            break
        chosen.append(c)
        covered |= c.moving
        frames += c.key_count
        rest.pop(0)
    everything: set = set()
    for c in clips:
        everything |= c.moving
    pool.clips = chosen
    pool.uncovered = sorted(set(pairs) - everything)
    return pool
